/* Navigation behaviour — shared by every page.
*
* Replaces two hand-maintained inline copies (site-scripts.php and an
* identical block in index.php) that had drifted apart and shared the same
* gaps: an unthrottled scroll listener, no aria-expanded, no Escape, no scroll
* lock, and no focus handling.
*
* Everything here is enhancement. The header is a working set of links before
* this runs; below 992px the noscript rules lay the menu out inline, so a
* failure to load leaves navigation usable rather than trapped behind a button.
*/
(function () {
var navbar = document.getElementById('navbar');
var toggle = document.getElementById('navToggle');
var menu = document.getElementById('mobileMenu');
/* ---- sticky state ------------------------------------------------
* The old handler ran on every scroll event and wrote a class each time.
* requestAnimationFrame coalesces that to at most one write per frame, and
* the class is only touched when the state actually changes. */
if (navbar) {
var scrolled = null;
var ticking = false;
function readScroll() {
ticking = false;
var next = window.scrollY > 20;
if (next !== scrolled) {
scrolled = next;
navbar.classList.toggle('scrolled', next);
}
}
window.addEventListener('scroll', function () {
if (!ticking) { ticking = true; window.requestAnimationFrame(readScroll); }
}, { passive: true });
readScroll();
}
if (!toggle || !menu) return;
var icon = toggle.querySelector('[data-lucide]');
var lastFocus = null;
function setIcon(name) {
if (!icon) return;
icon.setAttribute('data-lucide', name);
if (window.lucide && typeof window.lucide.createIcons === 'function') {
window.lucide.createIcons();
icon = toggle.querySelector('[data-lucide]');
}
}
function open() {
lastFocus = document.activeElement;
menu.classList.add('open');
toggle.setAttribute('aria-expanded', 'true');
toggle.setAttribute('aria-label', 'Close menu');
setIcon('x');
// Stop the page scrolling behind the panel.
document.body.style.overflow = 'hidden';
var first = menu.querySelector('a, button');
if (first) first.focus();
}
function close(returnFocus) {
if (!menu.classList.contains('open')) return;
menu.classList.remove('open');
toggle.setAttribute('aria-expanded', 'false');
toggle.setAttribute('aria-label', 'Open menu');
setIcon('menu');
document.body.style.overflow = '';
if (returnFocus) {
(lastFocus && document.contains(lastFocus) ? lastFocus : toggle).focus();
}
}
toggle.addEventListener('click', function () {
if (menu.classList.contains('open')) { close(true); } else { open(); }
});
// Following a link closes the panel, but focus must not be yanked back to
// the toggle mid-navigation.
menu.querySelectorAll('a').forEach(function (a) {
a.addEventListener('click', function () { close(false); });
});
document.addEventListener('keydown', function (e) {
if (e.key === 'Escape' && menu.classList.contains('open')) close(true);
});
// Crossing into the desktop layout leaves the panel open but hidden, with
// the body still locked. Close it so the page is never stuck unscrollable.
var desktop = window.matchMedia('(min-width: 992px)');
var onChange = function (e) { if (e.matches) close(false); };
if (desktop.addEventListener) { desktop.addEventListener('change', onChange); }
else if (desktop.addListener) { desktop.addListener(onChange); }
})();